from pathlib import Path
import base64

def replace_once(path_text: str, old: str, new: str) -> None:
    path = Path(path_text)
    text = path.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path_text}: expected one replacement, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

def write_b64(path_text: str, payload: str) -> None:
    Path(path_text).write_text(base64.b64decode(payload).decode("utf-8"), encoding="utf-8")

